package com.hs.listing.model; import com.hs.listing.model.constant.FurnishingStatus; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal;
@Entity @Table(name="listing_house_details") @Getter @Setter @NoArgsConstructor public class ListingHouseDetail { @Id private String listingId; @MapsId @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="listing_id") private Listing listing; @Column(name="land_area_m2") private BigDecimal landAreaM2; @Column(name="frontage_width_m") private BigDecimal frontageWidthM; @Column(name="length_m") private BigDecimal lengthM; @Column(name="access_road_width_m") private BigDecimal accessRoadWidthM; @Column(name="frontage_count") private Integer frontageCount; @Column(name="total_floors",nullable=false) private Integer totalFloors; @Column(name="bedroom_count",nullable=false) private Integer bedroomCount; @Column(name="bathroom_count",nullable=false) private Integer bathroomCount; @Column(name="living_room_count") private Integer livingRoomCount; @Column(name="kitchen_count") private Integer kitchenCount; @Column(name="has_rooftop") private Boolean hasRooftop; @Column(name="has_garage") private Boolean hasGarage; @Column(name="access_type") private String accessType; @Column(name="max_occupants") private Integer maxOccupants; @Column(name="max_vehicles") private Integer maxVehicles; @Enumerated(EnumType.STRING) @Column(name="furnishing_status",nullable=false) private FurnishingStatus furnishingStatus; @Column(name="legal_status") private String legalStatus; @Column(name="rental_scope_description") private String rentalScopeDescription; @Column(name="rented_floor_from") private Integer rentedFloorFrom; @Column(name="rented_floor_to") private Integer rentedFloorTo; }
